const body = $input.first().json;
const fields = body.data?.fields ?? body.fields ?? [];

const valueFor = (...labels) => {
  const match = fields.find((field) => {
    const label = String(field.label ?? field.key ?? '').toLowerCase();
    const type = String(field.type ?? '').toLowerCase();
    return (
      labels.some((wanted) => label.includes(wanted)) ||
      (wantedHasEmail(labels) && type.includes('email'))
    );
  });
  const raw = match?.value ?? match?.text ?? '';
  return Array.isArray(raw) ? String(raw[0] ?? '') : String(raw);
};

function wantedHasEmail(labels) {
  return labels.includes('email');
}

const email = valueFor('email');
const fullName = valueFor('name', 'full name') || email.split('@')[0] || 'Tally lead';
const parts = fullName.trim().split(/\s+/);
const firstName = parts[0] ?? '';
const lastName = parts.slice(1).join(' ');
const companyName = valueFor('company', 'organisation', 'organization');

if (!email) {
  throw new Error('Tally payload has no email field');
}

return [
  {
    json: {
      email,
      firstName,
      lastName,
      companyName,
      createPersonBody: {
        name: { firstName, lastName },
        emails: { primaryEmail: email },
      },
    },
  },
];

const mapped = $('Map Tally fields').first().json;
const created = $input.first().json;
const personId = created.data?.id ?? created.id;

if (!personId) {
  throw new Error('createPerson did not return an id');
}

const dealName = mapped.companyName
  ? `${mapped.companyName} — inbound`
  : `${mapped.firstName} ${mapped.lastName} — inbound`.trim();

return [
  {
    json: {
      personId,
      createOpportunityBody: {
        name: dealName,
        stage: $env.TWENTY_INBOUND_STAGE || 'WARM_CONTACT',
        pointOfContactId: personId,
      },
    },
  },
];
